{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE VIEW snitch_db.maplemonk.v_pricing_gp_floor AS WITH f_fsn_style AS ( SELECT DISTINCT fsn, REGEXP_REPLACE(style_code, \'-(XS|S|M|L|XL|XXL|XXXL)$\', \'\') AS style_code FROM v_s3_mtd_inventory WHERE fsn IS NOT NULL AND style_code IS NOT NULL UNION SELECT DISTINCT fsn, REGEXP_REPLACE(style_code, \'-(XS|S|M|L|XL|XXL|XXXL)$\', \'\') AS style_code FROM s3_fk_grn_ytd WHERE fsn IS NOT NULL AND style_code IS NOT NULL ), fk_sales AS ( SELECT f.style_code, SUM(CASE WHEN TO_DATE(TO_VARCHAR(s.order_date_key),\'YYYYMMDD\') >= DATEADD(day,-90,CURRENT_DATE()) THEN s.units ELSE 0 END) AS units_90d, SUM(CASE WHEN TO_DATE(TO_VARCHAR(s.order_date_key),\'YYYYMMDD\') >= DATEADD(day,-28,CURRENT_DATE()) THEN s.units ELSE 0 END) AS units_28d FROM v_s3_mtd_sales s JOIN f_fsn_style f ON s.fsn = f.fsn GROUP BY 1 ), fk_soh AS ( SELECT f.style_code, SUM(i.qoh) AS current_soh FROM v_s3_mtd_inventory i JOIN f_fsn_style f ON i.fsn = f.fsn GROUP BY 1 ), fk_grn AS ( SELECT f.style_code, MAX(TO_DATE(TO_VARCHAR(g.grn_created_date_key),\'YYYYMMDD\')) AS last_received_at FROM s3_fk_grn_ytd g JOIN f_fsn_style f ON g.fsn = f.fsn GROUP BY 1 ), fk_combined AS ( SELECT \'Flipkart\' AS channel, CAST(soh.style_code AS VARCHAR) AS style, COALESCE(soh.current_soh,0) AS current_soh, COALESCE(sales.units_90d,0) AS units_90d, COALESCE(sales.units_28d,0) AS units_28d, grn.last_received_at FROM fk_soh soh LEFT JOIN fk_sales sales ON sales.style_code = soh.style_code LEFT JOIN fk_grn grn ON grn.style_code = soh.style_code ), myn_sales AS ( SELECT CAST(s.style_id AS VARCHAR) AS style, SUM(CASE WHEN TO_DATE(TO_VARCHAR(s.order_created_date),\'YYYYMMDD\') >= DATEADD(day,-90,CURRENT_DATE()) THEN s.sales ELSE 0 END) AS units_90d, SUM(CASE WHEN TO_DATE(TO_VARCHAR(s.order_created_date),\'YYYYMMDD\') >= DATEADD(day,-28,CURRENT_DATE()) THEN s.sales ELSE 0 END) AS units_28d FROM s3_soh_sales s GROUP BY 1 ), myn_soh AS ( SELECT CAST(style_id AS VARCHAR) AS style, SUM(soh) AS current_soh FROM s3_soh_inventory GROUP BY 1 ), myn_grn AS ( SELECT CAST(m.style_id AS VARCHAR) AS style, MAX(TRY_TO_DATE(g.received_at)) AS last_received_at FROM s3_myntra_historical_grn g JOIN myntra_sku_master m ON g.sku_code = m.sku_code GROUP BY 1 ), myn_combined AS ( SELECT \'Myntra\' AS channel, soh.style AS style, COALESCE(soh.current_soh,0) AS current_soh, COALESCE(sales.units_90d,0) AS units_90d, COALESCE(sales.units_28d,0) AS units_28d, grn.last_received_at FROM myn_soh soh LEFT JOIN myn_sales sales ON sales.style = soh.style LEFT JOIN myn_grn grn ON grn.style = soh.style ), base AS ( SELECT * FROM fk_combined UNION ALL SELECT * FROM myn_combined ), enriched AS ( SELECT channel, style, current_soh, units_90d, units_28d, last_received_at, DIV0(units_90d, NULLIF(units_90d + current_soh,0)) * 100 AS str_pct, DIV0(current_soh, NULLIF(units_28d,0)) * 28 AS doi_days, DATEDIFF(day, last_received_at, CURRENT_DATE()) AS days_since_last_grn FROM base ), tiered AS ( SELECT *, CASE WHEN str_pct > 5 THEN \'head\' WHEN str_pct >= 3 THEN \'belly\' ELSE \'tail\' END AS str_tier, CASE WHEN days_since_last_grn > 90 OR last_received_at IS NULL THEN TRUE ELSE FALSE END AS is_aged, CASE WHEN doi_days >= 90 THEN TRUE ELSE FALSE END AS is_high_doi FROM enriched ), floors AS ( SELECT *, CASE str_tier WHEN \'head\' THEN 60 WHEN \'belly\' THEN 55 ELSE 45 END - CASE WHEN is_aged THEN 5 ELSE 0 END - CASE WHEN is_high_doi THEN 5 ELSE 0 END AS tier_floor_pre_min, CASE WHEN current_soh < 50 THEN CASE WHEN current_soh >= 40 THEN 30 WHEN current_soh >= 25 THEN 27 WHEN current_soh >= 10 THEN 23 WHEN current_soh >= 1 THEN 20 ELSE 20 END ELSE NULL END AS clearance_floor FROM tiered ) SELECT channel, style, str_tier, ROUND(str_pct,2) AS str_pct, current_soh, ROUND(doi_days,1) AS doi_days, is_aged, is_high_doi, last_received_at, GREATEST(tier_floor_pre_min, 30) AS tier_floor_pct, clearance_floor, CASE WHEN clearance_floor IS NOT NULL THEN LEAST(GREATEST(tier_floor_pre_min, 30), clearance_floor) ELSE GREATEST(tier_floor_pre_min, 30) END AS effective_floor_pct, CASE WHEN clearance_floor IS NOT NULL THEN \'LOW_INVENTORY_EXIT\' ELSE \'ACTIVE\' END AS row_status FROM floors; CREATE OR REPLACE VIEW snitch_db.maplemonk.v_pricing_low_inventory_exit AS SELECT * FROM snitch_db.maplemonk.v_pricing_gp_floor WHERE row_status = \'LOW_INVENTORY_EXIT\' ORDER BY channel, current_soh; CREATE OR REPLACE VIEW snitch_db.maplemonk.v_pricing_overstock_alert AS SELECT * FROM snitch_db.maplemonk.v_pricing_gp_floor WHERE row_status = \'ACTIVE\' AND is_high_doi = TRUE ORDER BY channel, doi_days DESC; CREATE OR REPLACE VIEW snitch_db.maplemonk.v_chart3_ro_funnel AS WITH f_ro AS ( SELECT DATE_TRUNC(\'month\', TO_DATE(RO_DATE)) AS ro_month, RO_NUMBER, QTY, UPPER(RO_STATUS) AS ro_status FROM snitch_db.maplemonk.s3_flipkart_ro WHERE TO_DATE(RO_DATE) >= TO_DATE(\'2026-04-01\') ), f_chart AS ( SELECT ro_month AS month, \'FLIPKART_SOR\' AS channel, COUNT(DISTINCT RO_NUMBER) AS ro_count, SUM(QTY) AS ro_raised_qty, SUM(CASE WHEN ro_status = \'COMPLETED\' THEN QTY ELSE 0 END) AS ro_approved_qty, CASE WHEN SUM(QTY) > 0 THEN ROUND(SUM(CASE WHEN ro_status = \'COMPLETED\' THEN QTY ELSE 0 END) / NULLIF(SUM(QTY),0) * 100, 2) ELSE NULL END AS approved_pct FROM f_ro GROUP BY ro_month ), m_ro AS ( SELECT DATE_TRUNC(\'month\', REJECTED_ON) AS ro_month, RO_BARCODE FROM snitch_db.maplemonk.s3_myntra_historic_ro WHERE REJECTED_ON >= \'2026-04-01\' AND RO_TYPE = \'SOR_ITEM\' ), m_chart AS ( SELECT ro_month AS month, \'MYNTRA\' AS channel, COUNT(DISTINCT RO_BARCODE) AS ro_count, COUNT(*) AS ro_raised_qty, CAST(NULL AS NUMBER(38,0)) AS ro_approved_qty, CAST(NULL AS NUMBER(38,2)) AS approved_pct FROM m_ro GROUP BY ro_month ) SELECT * FROM f_chart UNION ALL SELECT * FROM m_chart ORDER BY month DESC, channel;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            